U.add('aes','adv_lcdgray',{sev:5.13,name:'LCD GRAY',ax:{x:0.408,n:0.941,v:0.991},new:'four-shade handheld LCD: one green-gray ink on one green-gray ground, no other colour exists',css:`&{background:#9cae8a;color:#1c2516;font:14px monospace;letter-spacing:1px}& .win{background:#8fa27e;border:4px solid #1c2516;padding:12px}& *{font-family:monospace}& button,& input,& select,& textarea{background:#8fa27e;color:#1c2516;border:2px solid #1c2516;border-radius:0}& h1{font-size:18px;text-transform:uppercase}`});
