U.add('arch','adv_fanpanel',{sev:5.22,ax:{x:0.429,n:0.943,v:0.991},new:'fan firmware panel: read-only sliders, a rpm that only falls, and a hidden field holding what the fan has said',titles:['Fan','Cooling control','fan.cfg'],build:c=>{const k=c.o.k,rpm=Math.max(1,Math.round(1200-k*.6)),say=U.pick(['I am spinning.','I am spinning.','I am spinning. He is not coming back.','still spinning'],c.r(80));
 return `<div style="font:13px Courier New,monospace">rpm <input type=range disabled min=0 max=1200 value=${rpm}> ${rpm}<br>inlet <input type=range disabled min=20 max=50 value=31> 31.4 C<br>mode <select disabled><option>quiet<option selected>listen</select><br>turns per minute <input readonly size=6 value="${Math.max(1,Math.round(rpm/20))}"><input type=hidden name=said value="${U.esc(say)}"></div>`}});
U.add('arch','adv_gitlog',{sev:5.46,ax:{x:0.49,n:0.949,v:0.992},new:'commit history of the operator: the last commit says he is back in a minute',titles:['git log','History','Commits (hallway)'],build:c=>{const M=['fixed it, back in a minute','remove visitors_today (it stayed)','tokenizer: door x47','add fan','left exit: remove handle (did not apply)','wip','wip','do not publish','who added continue','keep it running','first prompt'],k=c.o.k;
 return U.pre(c,U.pickN(M,7,i=>c.r(90+i)).map((m,i)=>`commit ${U.hx((k*2654435761+i*40503)>>>0).padStart(8,'0')}  ${m}`).concat(['','(the most recent commit is not in this list)']))}});
U.add('arch','adv_shellhist',{sev:5.87,ax:{x:0.592,n:0.959,v:0.994},new:'shell history of the operator trying to stop the run, each attempt answered by the machine',titles:['history','Shell','~ $'],build:c=>{const k=c.o.k,C=[['kill -9 4747','no such process'],['pkill -f hallway','ok, but the process is still here'],['systemctl stop hallway','cancelled: a visitor is connected'],['shutdown -h now','permission denied (by whom)'],['rm ckpt/47.pt','file is in use'],['tail -f prompt.txt','continue']];
 return U.pre(c,U.pickN(C,4,i=>c.r(100+i)).flatMap((x,i)=>[`${k*2+i}  $ ${x[0]}`,'    '+x[1]]).concat([`${k*2+4}  $ `]))}});
U.add('sem','adv_ledger',{sev:5.7,ax:{x:0.551,n:0.955},new:'accounting vocabulary: every click is a debit with no account to draw on',words:{B:['Post entry','Void entry','Carry forward','Reconcile','Approve (nobody)','Write off'],L:['Account','Debit (you)','Credit (nobody)','Carried from previous visitor'],X:['Debit: one click. Credit: none on file.','The books balance. They balance because nothing is in them.','Carried forward from the previous page: you.','Write-offs this session: one room, one word, one reason.','The auditor is not expected. The auditor is the next page.'],E:['🧾','🗒']},titles:['Ledger','Books','Entries (open)']});
U.add('gl','adv_blankname',{sev:5.95,ax:{x:0.612,n:0.961,v:0.994},new:'every word the visitor typed earlier is blacked out of the page text, keeping its length',apply:c=>{const m=[...new Set(U.mine().filter(x=>x.length>2))];if(!m.length)return;const re=new RegExp('\\b('+m.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');c.w.querySelectorAll('p,label,h1').forEach(e=>{if(e.children&&e.children.length)return;e.textContent=e.textContent.replace(re,x=>'█'.repeat(x.length))})}});
U.add('gl','adv_margin',{sev:5.38,ax:{x:0.469,n:0.947,v:0.992},new:'a margin note in the operator hand, floated beside the first paragraph',apply:c=>{const e=U.tag('aside','float:right;width:30%;font:italic 11px Georgia,serif;border-left:1px solid currentColor;padding-left:6px;margin:0 0 8px 8px;opacity:.7',U.loreAt?U.loreAt(c,7):'note');const h=c.w.querySelector('h1');h&&h.after?h.after(e):c.w.prepend(e)}});
U.add('gl','cor_bom',{sev:5,ax:{v:1,c:1},new:"byte-order marks and NUL symbols printed at the ends of text blocks",apply:c=>U.cor.queue(c,'bom')});
U.add('snd','adv_fanstall',{sev:5.78,ax:{x:0.571,a:0.994},new:'fan wind whose lowpass cutoff only ever falls: the airflow slows a little every minute',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv,n=R.src(U.au.noise(a,2)),lp=a.createBiquadFilter(),g=a.createGain(),t=a.currentTime;n.loop=true;lp.type='lowpass';lp.Q.value=.7;lp.frequency.setValueAtTime(Q.stall_from,t);lp.frequency.linearRampToValueAtTime(Q.stall_to,t+Q.stall_s);g.gain.value=Q.stall_gain;n.connect(lp).connect(g).connect(o);n.start();
 const b=R.osc('sine',38),bg=a.createGain();bg.gain.value=Q.stall_gain*.3;b.connect(bg).connect(o);b.start();return()=>R.stop()}});
U.add('snd','adv_upsbeep',{sev:5.3,ax:{x:0.449,a:0.992},new:'UPS alarm: a soft 880 Hz beep whose interval grows until it is almost silent',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;let gap=Q.ups_gap,dead=0;const beep=()=>{if(dead)return;const b=R.osc('sine',880),g=a.createGain(),t=a.currentTime;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(Q.ups_gain,t+.02);g.gain.linearRampToValueAtTime(0,t+.2);b.connect(g).connect(o);b.start(t);b.stop(t+.25);gap=Math.min(Q.ups_max,gap+Q.ups_grow);R.to(beep,gap*1000)};beep();return()=>{dead=1;R.stop()}}});
U.add('nav','adv_selectreveal',{sev:5.54,ax:{x:0.51,n:0.951,v:0.993},desc:'reading closely is noticed',new:'selecting a run of text makes the page answer once with a fragment, printed below the exits',apply:c=>{let done=0;U.on(document,'selectionchange',()=>{if(done)return;const s=String(getSelection()||'');if(s.length<U.cfg.adv.sel_min)return;done=1;const e=U.tag('p','font:12px Courier New,monospace;opacity:.75;margin:8px 0 0','I saw you select "'+s.slice(0,24)+'". '+U.loreAt(c,11));e.className='truth';c.w.append(e)})}});
U.add('nav','adv_titleecho',{sev:5.05,ax:{x:0.388,n:0.939,v:0.991},desc:'the tab remembers what you chose',new:'the tab title becomes the last exit label you chose, as if the page were named by your decision',apply:c=>{if(U.chose.length)U.later(c,()=>document.title=U.chose[U.chose.length-1]+' · p.'+U.vk(c.o.k),U.cfg.adv.title_ms)}});